def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class Point:
        def __init__(self, *args, **kwargs):
            self.fields = fields
            self.srid_map = srid_map
            self.values = {}
            for i, field in enumerate(fields):
                if i < len(args):
                    self.values[field] = args[i]
                elif field in kwargs:
                    self.values[field] = kwargs[field]
                else:
                    self.values[field] = None
            self.srid = kwargs.get('srid', None)
            if self.srid is not None and self.srid not in srid_map:
                raise ValueError(f"Unknown SRID: {self.srid}")

        def __repr__(self):
            field_strs = [f"{field}={self.values[field]!r}" for field in self.fields]
            srid_str = f", srid={self.srid!r}" if self.srid is not None else ""
            return f"{name}({', '.join(field_strs)}{srid_str})"

    Point.__name__ = name
    return Point

