def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if not cmd:
        return cmd
    if not sys.platform.startswith('win'):
        return cmd
    # On Windows, if the command is a Python script, we need to prepend the Python interpreter
    # This handles the case where the script has a shebang line, which Windows ignores
    # Also handles deep-path shebangs by ensuring the interpreter is correctly identified
    if len(cmd) > 0:
        first = cmd[0]
        # Check if the first element looks like a Python script (ends with .py or is a known Python script)
        # We'll check if it's a file that exists and has a shebang line
        try:
            # Check if it's a file
            if os.path.isfile(first):
                # Read the first line to check for shebang
                with open(first, 'r', encoding='utf-8', errors='ignore') as f:
                    first_line = f.readline().strip()
                if first_line.startswith('#!'):
                    # Extract the interpreter from the shebang
                    # The shebang line is in the format: #! /path/to/interpreter [args]
                    parts = first_line[2:].strip().split()
                    if parts:
                        interpreter = parts[0]
                        # If the interpreter is a relative path, make it absolute
                        if not os.path.isabs(interpreter):
                            # Try to find the interpreter in PATH
                            interpreter_path = shutil.which(interpreter)
                            if interpreter_path:
                                interpreter = interpreter_path
                            else:
                                # If not found, keep as is
                                pass
                        # Prepend the interpreter to the command
                        return (interpreter, first) + cmd[1:]
        except (IOError, OSError):
            # If we can't read the file, just return the original command
            pass
    return cmd

