def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        freq = {}
        min_freq = 0
        freq_buckets = {}

        def _make_key(args, kwargs):
            if typed:
                key = (args, kwargs)
            else:
                key = (args, tuple(sorted(kwargs.items())))
            return key

        def _evict():
            nonlocal min_freq
            if min_freq in freq_buckets:
                bucket = freq_buckets[min_freq]
                if bucket:
                    key = bucket.pop()
                    del cache[key]
                    del freq[key]
                    if not bucket:
                        del freq_buckets[min_freq]
                    if min_freq in freq_buckets and not freq_buckets[min_freq]:
                        del freq_buckets[min_freq]
                    # Find new min_freq
                    while min_freq in freq_buckets and not freq_buckets[min_freq]:
                        min_freq += 1
                    if min_freq not in freq_buckets:
                        # Find the smallest frequency that exists
                        for f in sorted(freq_buckets.keys()):
                            if freq_buckets[f]:
                                min_freq = f
                                break
                        else:
                            min_freq = 0

        def wrapper(*args, **kwargs):
            nonlocal min_freq
            key = _make_key(args, kwargs)
            if key in cache:
                # Update frequency
                f = freq[key]
                # Remove from current bucket
                bucket = freq_buckets[f]
                bucket.remove(key)
                if not bucket:
                    del freq_buckets[f]
                # Add to new bucket
                new_f = f + 1
                freq[key] = new_f
                if new_f not in freq_buckets:
                    freq_buckets[new_f] = []
                freq_buckets[new_f].append(key)
                # Update min_freq if needed
                if min_freq == f and not freq_buckets.get(f, []):
                    min_freq = new_f
                return cache[key]

            # If cache is full, evict
            if len(cache) >= maxsize:
                _evict()

            # Compute and store
            result = func(*args, **kwargs)
            cache[key] = result
            freq[key] = 1
            if 1 not in freq_buckets:
                freq_buckets[1] = []
            freq_buckets[1].append(key)
            min_freq = 1
            return result

        wrapper.cache = cache
        wrapper.cache_clear = lambda: (cache.clear(), freq.clear(), freq_buckets.clear(), setattr(wrapper, 'min_freq', 0))
        return wrapper
    return decorator

