def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    # Remove duplicates while preserving order
    seen = set()
    unique_classes = []
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            unique_classes.append(cls)

    # Remove any class that is a subclass of another class in the list
    # We want to keep only the most specific (leaf) classes
    minimal = []
    for i, cls in enumerate(unique_classes):
        # Check if cls is a subclass of any other class in unique_classes
        is_subclass_of_other = False
        for j, other in enumerate(unique_classes):
            if i != j and issubclass(cls, other):
                is_subclass_of_other = True
                break
        if not is_subclass_of_other:
            minimal.append(cls)

    return minimal

