def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        # Check if coord is within the histogram edges
        if self._edges is None:
            return
        if len(coord) != len(self._edges) - 1:
            return
        for i, c in enumerate(coord):
            if c < self._edges[i] or c >= self._edges[i + 1]:
                return
        # Find the bin index
        bin_index = 0
        for i in range(len(self._edges) - 1):
            if self._edges[i] <= c < self._edges[i + 1]:
                bin_index = i
                break
        # Increment the histogram at the bin index
        self._hist[bin_index] += weight

