def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary")

    if 'files' not in fixity:
        raise ValueError("Fixity must contain a 'files' key")

    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("Fixity 'files' must be a list")

    for file_entry in files:
        if not isinstance(file_entry, dict):
            raise ValueError("Each file entry in fixity must be a dictionary")

        if 'path' not in file_entry:
            raise ValueError("Each file entry in fixity must contain a 'path' key")

        file_path = file_entry['path']
        if not isinstance(file_path, str):
            raise ValueError("File path in fixity must be a string")

        if file_path not in manifest_files:
            raise ValueError(f"File {file_path} in fixity is not listed in the manifest")

    return True

