def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not version_dirs:
        return

    # Initialize a dictionary to store content digests that differ from the root inventory
    self._different_content_digests = {}

    # Get the root inventory for comparison
    root_inventory = self._get_root_inventory()

    for version_dir in version_dirs:
        # Check if the version directory exists
        if not self._version_dir_exists(version_dir):
            continue

        # Get the inventory for this version
        version_inventory = self._get_version_inventory(version_dir)

        if version_inventory is None:
            continue

        # Compare content digests with the root inventory
        for content_id, digest in version_inventory.items():
            if content_id in root_inventory:
                root_digest = root_inventory[content_id]
                if digest != root_digest:
                    # Record the different content digest
                    if content_id not in self._different_content_digests:
                        self._different_content_digests[content_id] = []
                    self._different_content_digests[content_id].append((version_dir, digest))
            else:
                # Content not in root inventory, record it
                if content_id not in self._different_content_digests:
                    self._different_content_digests[content_id] = []
                self._different_content_digests[content_id].append((version_dir, digest))

