def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Check if we're on Windows
        if os.name != 'nt':
            return False

        # Check for git bash specific environment variables
        # Git Bash sets MSYSTEM to MINGW64 or MINGW32
        if 'MSYSTEM' in os.environ:
            return True

        # Alternative check: look for git bash in the PATH or command
        # Check if we're running under git bash by looking at the shell
        if 'GIT_BASH' in os.environ:
            return True

        # Check if the current shell is git bash
        if 'COMSPEC' in os.environ:
            comspec = os.environ['COMSPEC'].lower()
            if 'git' in comspec and 'bash' in comspec:
                return True

        # Check for git bash in the PATH
        path = os.environ.get('PATH', '')
        if 'git' in path.lower() and 'bash' in path.lower():
            # More specific check: look for git bash executable
            if 'git-bash' in path.lower() or 'gitbash' in path.lower():
                return True

        return False

    except Exception:
        return False

