def _resolve_string(matcher):
    if not isinstance(matcher, str):
        raise TypeError("matcher must be a string")

    # Split on the first '=' to separate name and default value
    if '=' in matcher:
        name, default_value = matcher.split('=', 1)
    else:
        name = matcher
        default_value = None

    # Get the value from the environment
    value = os.environ.get(name)

    # If the variable is not defined in the environment
    if value is None:
        # If a default value is provided, use it
        if default_value is not None:
            return default_value
        # Otherwise, raise an error
        raise EnvironmentError(f"Environment variable '{name}' is not set and no default value provided")

    return value

