def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import logging

    import os

    import json

    import yaml

    import re

    def _apply_overrides(config, overrides):
        """
        Apply overrides to the configuration.
        """
        if not isinstance(config, dict):
            return config

        result = config.copy()
        for key, value in overrides.items():
            if key in result:
                if isinstance(result[key], dict) and isinstance(value, dict):
                    result[key] = _apply_overrides(result[key], value)
                else:
                    result[key] = value
            else:
                result[key] = value
        return result

    def _resolve_env_vars(config):
        """
        Resolve environment variables in the configuration.
        """
        if isinstance(config, dict):
            return {key: _resolve_env_vars(value) for key, value in config.items()}
        elif isinstance(config, list):
            return [_resolve_env_vars(item) for item in config]
        elif isinstance(config, str):
            # Resolve environment variables in the string
            def replace_env(match):
                var_name = match.group(1)
                return os.environ.get(var_name, match.group(0))

            # Match ${VAR} or $VAR patterns
            config = re.sub(r'\$\{([^}]+)\}', replace_env, config)
            config = re.sub(r'\$([A-Za-z_][A-Za-z0-9_]*)', replace_env, config)
            return config
        else:
            return config
    if overrides is None:
        overrides = {}

    config_dict = {}
    error_records = []

    # Create a logger for capturing errors
    logger = logging.getLogger("config_loader")
    logger.setLevel(logging.ERROR)

    # Create a handler to capture log records
    class ListHandler(logging.Handler):
        def __init__(self):
            super().__init__()
            self.records = []

        def emit(self, record):
            self.records.append(record)

    handler = ListHandler()
    logger.addHandler(handler)

    for filename in config_filenames:
        try:
            # Check if file exists
            if not os.path.exists(filename):
                raise FileNotFoundError(f"Configuration file not found: {filename}")

            # Determine file type by extension
            ext = os.path.splitext(filename)[1].lower()

            if ext == '.json':
                with open(filename, 'r') as f:
                    config = json.load(f)
            elif ext in ['.yaml', '.yml']:
                with open(filename, 'r') as f:
                    config = yaml.safe_load(f)
            else:
                # Try JSON first, then YAML
                with open(filename, 'r') as f:
                    content = f.read()
                try:
                    config = json.loads(content)
                except json.JSONDecodeError:
                    config = yaml.safe_load(content)

            # Apply overrides
            if overrides:
                config = _apply_overrides(config, overrides)

            # Resolve environment variables if requested
            if resolve_env:
                config = _resolve_env_vars(config)

            config_dict[filename] = config

        except Exception as e:
            # Log the error
            logger.error(f"Error loading configuration file {filename}: {str(e)}")

    # Remove the handler
    logger.removeHandler(handler)

    return config_dict, handler.records

