def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json

    from typing import Dict

    from xml.etree import ElementTree
    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            return data
    except (json.JSONDecodeError, ValueError):
        pass

    # Try XRD (XML)
    try:
        root = ElementTree.fromstring(document)
        result = {}

        # XRD structure: <XRD xmlns="http://docs.oasis-open.org/webfinger/xrd/1.0">
        # We need to handle namespaces
        ns = {'xrd': 'http://docs.oasis-open.org/webfinger/xrd/1.0'}

        # Get subject
        subject_elem = root.find('xrd:subject', ns)
        if subject_elem is not None:
            result['subject'] = subject_elem.text

        # Get aliases
        aliases = []
        for alias_elem in root.findall('xrd:alias', ns):
            if alias_elem.text:
                aliases.append(alias_elem.text)
        if aliases:
            result['aliases'] = aliases

        # Get links
        links = []
        for link_elem in root.findall('xrd:link', ns):
            link = {}
            for attr in ['rel', 'type', 'href']:
                if attr in link_elem.attrib:
                    link[attr] = link_elem.attrib[attr]
            if link:
                links.append(link)
        if links:
            result['links'] = links

        return result
    except ElementTree.ParseError:
        pass

    # If neither JSON nor XRD, return empty dict or raise
    return {}

