def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    if not ir_workspace or not ir_plugin:
        raise ValueError("ir_workspace and ir_plugin must be provided")
    if not playbook_path:
        raise ValueError("playbook_path must be provided")

    # Build the base command
    cmd = ["ansible-playbook"]

    # Add verbosity if specified
    if verbose is not None:
        if not isinstance(verbose, int) or verbose < 0:
            raise ValueError("verbose must be a non-negative integer")
        cmd.append("-" + "v" * verbose)

    # Add extra vars if provided
    if extra_vars is not None:
        if not isinstance(extra_vars, dict):
            raise ValueError("extra_vars must be a dictionary")
        for key, value in extra_vars.items():
            cmd.append(f"--extra-vars {key}={value}")

    # Add any additional ansible-playbook arguments
    if ansible_args is not None:
        if not isinstance(ansible_args, dict):
            raise ValueError("ansible_args must be a dictionary")
        for arg, value in ansible_args.items():
            if value is None:
                cmd.append(f"--{arg}")
            else:
                cmd.append(f"--{arg} {value}")

    # Add the playbook path
    cmd.append(playbook_path)

    # Execute the command using the workspace's shell execution method
    try:
        result = ir_workspace.run_command(cmd)
        return result
    except Exception as e:
        raise RuntimeError(f"Failed to execute ansible-playbook: {str(e)}")

