def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Get the parser for the given command
    parser = self._parsers.get(parser_name)
    if parser is None:
        return

    # Iterate over the arguments in the parser
    for action in parser._actions:
        if action.dest in values_dict:
            value = values_dict[action.dest]
            # If the value is a string, try to convert it to the expected type
            if isinstance(value, str):
                if action.type is not None:
                    try:
                        values_dict[action.dest] = action.type(value)
                    except (ValueError, TypeError):
                        # If conversion fails, keep the original value
                        pass
                elif action.const is not None and action.const != value:
                    # If the action has a const value and the current value is different,
                    # it might be a boolean flag
                    if value.lower() in ('true', '1', 'yes'):
                        values_dict[action.dest] = True
                    elif value.lower() in ('false', '0', 'no'):
                        values_dict[action.dest] = False

